class MinHeap {
  private a: number[] = [];
  get size(): number { return this.a.length; }
  peek(): number { return this.a[0]; }
  push(x: number): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function roomsNeeded(meetings: number[][]): number {
  const m = meetings.map(x => [x[0], x[1]]).sort((a, b) => a[0] - b[0]);
  const ends = new MinHeap();
  let best = 0;
  for (const [s, e] of m) {
    if (ends.size && ends.peek() <= s) ends.pop(); // that room is free again
    ends.push(e);
    best = Math.max(best, ends.size);
  }
  return best;
}

